\label{tab:variance_components}
\small
\begin{tabular}{lrrrr}
\toprule
Component & \% Var & SE & 95\% CI \\
\midrule
item\_id & 58.4 & 2.1 & [54.3, 62.5] \\
residual & 16.8 & 0.9 & [15.0, 18.6] \\
prompt $\times$ item & 6.1 & 0.7 & [4.7, 7.5] \\
